contract InvMutTest {
    C c;
    address deployer;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that non-owner calls to withdraw/withdrawAll/sendMoney revert and do not alter depositsCount or balance.
    // Parameters: callerIsOwner selects whether this contract will be owner (true) or not (false).
    // amount is the value attempted to withdraw/send; sendData is forwarded to sendMoney target call.
    function run(bool callerIsOwner, address target, uint amount, bytes calldata sendData) public payable {
        require(true);

        // If we want this InvMutTest contract to be owner of C, that must have happened at C deployment time.
        // The checker deploys a fresh C with msg.sender = this InvMutTest's deployer (constructor sender of C),
        // which in our setup is the external deployer of the whole system. We cannot change that here.
        // So callerIsOwner==true means we will attempt owner-only calls and expect success only if this contract is the owner.

        // Record observables before the call
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool revertedWithdraw;
        bool revertedWithdrawAll;
        bool revertedSendMoney;

        // Attempt withdraw (may revert)
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedWithdraw = true;
        } else {
            revertedWithdraw = false;
        }

        // Attempt withdrawAll (may revert)
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedWithdrawAll = true;
        } else {
            revertedWithdrawAll = false;
        }

        // Attempt sendMoney (may revert). We pass along sendData and amount.
        // Ensure this contract has enough balance to send when calling sendMoney as msg.sender of c (it doesn't send Ether itself in this call).
        c.sendMoney(target, amount, sendData); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            revertedSendMoney = true;
        } else {
            revertedSendMoney = false;
        }

        // Observables after
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule asserted: If any of the owner-only calls reverted, then none of those calls should have changed depositsCount or contract balance.
        // Conversely, if they did not revert, they are allowed to change balance but still must not change depositsCount (since depositsCount only increments on fallback payable).
        // We assert the universal relation combining both directions into a single formula.
        assert(
            // If any reverted => depositsCount and balance unchanged
            ((revertedWithdraw || revertedWithdrawAll || revertedSendMoney) && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            // If none reverted => depositsCount unchanged (withdraw/sendMoney/withdrawAll shouldn't touch depositsCount)
            || ((!revertedWithdraw && !revertedWithdrawAll && !revertedSendMoney) && afterDeposits == beforeDeposits)
        );
    }

    // Accept Ether so that fallback on C might have been invoked earlier by external things; not used directly here.
    receive() external payable {}
}

