pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;
    address deployer;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(bool callerIsOwner, address target, uint256 amount, bytes memory sendData) internal {
        vm.assume(true);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool revertedWithdraw;
        bool revertedWithdrawAll;
        bool revertedSendMoney;
        try c.withdraw(amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }
        try c.sendMoney(target, amount, sendData) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(((revertedWithdraw || revertedWithdrawAll || revertedSendMoney) && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            // If none reverted => depositsCount unchanged (withdraw/sendMoney/withdrawAll shouldn't touch depositsCount)
            || ((!revertedWithdraw && !revertedWithdrawAll && !revertedSendMoney) && afterDeposits == beforeDeposits));
    }

    function testFuzz_run(bool callerIsOwner, address target, uint256 amount, bytes memory sendData) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(callerIsOwner, target, amount, sendData);
    }

    receive() external payable {}
}
